def fires(b):
    if b.ply > 20:
        return False
    for (r, c) in [(1, 2), (2, 2), (1, 4), (2, 4)]:
        if b.grid[r][c] == 2:
            return False
    return True

def vert3(b, p):
    for c in range(7):
        h = b.heights[c]
        if 3 <= h < 6 and all(b.grid[h - 1 - k][c] == p for k in range(3)):
            return True
    return False

def fires(b):
    return vert3(b, 2)

def opp_links(b):
    n = 0
    for r in range(6):
        for c in range(7):
            if b.grid[r][c] != 2:
                continue
            for dr, dc in [(0, 1), (1, 1), (1, -1)]:
                rr, cc = r + dr, c + dc
                if 0 <= rr < 6 and 0 <= cc < 7 and b.grid[rr][cc] == 2:
                    n += 1
    return n

def score(b):
    s = 0
    if b.ply <= 16:
        s += 2
    elif b.ply <= 22:
        s += 1
    if opp_links(b) <= 1:
        s += 1
    if b.heights[3] < 6 and b.heights[3] % 2 == 1:
        s += 1
    for (r, c) in [(1, 2), (2, 2), (1, 4), (2, 4)]:
        if b.grid[r][c] == 2:
            s -= 1
    return s

def fires(b):
    return score(b) >= 4

def level(b):
    return max(0, min(9, 2 * score(b)))

GOOD_THEM = [(1, 3), (0, 6), (0, 1), (2, 1), (2, 5)]
BAD_THEM = [(1, 2), (2, 2), (1, 4), (2, 4), (1, 5)]
GOOD_ME = [(1, 1), (1, 5)]
BAD_ME = [(0, 2), (0, 1)]

def score(b):
    g = b.grid
    s = 0
    s += sum(1 for (r, c) in GOOD_THEM if g[r][c] == 2)
    s -= sum(1 for (r, c) in BAD_THEM if g[r][c] == 2)
    s += sum(1 for (r, c) in GOOD_ME if g[r][c] == 1)
    s -= sum(1 for (r, c) in BAD_ME if g[r][c] == 1)
    if b.heights[3] == 6:
        s -= 1
    if b.ply > 24:
        s -= 1
    return s

def fires(b):
    return score(b) >= 3

def level(b):
    return max(0, min(9, 2 * score(b) + 2))
